import json
import os

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def get_json_secret(secret_name: str, region_name: str | None = None) -> dict:
    client = boto3.client(
        "secretsmanager",
        region_name=region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION"),
    )

    try:
        response = client.get_secret_value(SecretId=secret_name)
    except (ClientError, BotoCoreError) as exc:
        raise RuntimeError(f"Failed to retrieve secret from AWS Secrets Manager: {secret_name}") from exc

    secret_string = response.get("SecretString")
    if not secret_string:
        raise ValueError(f"Secret is missing SecretString or is binary-only: {secret_name}")

    try:
        parsed = json.loads(secret_string)
    except json.JSONDecodeError as exc:
        raise ValueError(f"SecretString is not valid JSON for secret: {secret_name}") from exc

    if not isinstance(parsed, dict):
        raise ValueError(f"Expected JSON object in secret: {secret_name}")

    return parsed
